   131→pub fn compute_subnets_for_node<P: Preset>(
   132→    raw_node_id: [u8; 32],
   133→    custody_group_count: u64,
   134→    config: &Config,
   135→) -> Result<HashSet<SubnetId>> {
   136→    let mut subnets = HashSet::new();
